def transform(grid):
    """Fill the empty cell between horizontally adjacent 4s with 2."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(len(row) - 2):
            if row[c] == 4 and row[c + 1] == 1 and row[c + 2] == 4:
                out[r][c + 1] = 2
    return out

